#include <TSStd_Types_Arch.h>   /* target specific standard types */

/*==================[macros]=================================================*/

#if (defined TS_VENDOR_ID_CYPRESS) /* guard to prevent double declaration */
#error TS_VENDOR_ID_CYPRESS already defined
#endif /* if (defined TS_VENDOR_ID_CYPRESS) */

/** \brief definition of the unique vendor ID
 *
 * This vendor ID is based on the vendor ID published by the HIS.
 * It should be used for each module */
#define TS_VENDOR_ID_CYPRESS 66U

#if (defined TS_NULL) /* guard to prevent double declaration */
#error TS_NULL already defined
#endif /* if (defined TS_NULL) */

#if (!defined NULL)
/** \brief abstraction of an ISO-C:99 keyword for \p NULL */
#define TS_NULL 0U
#else /* if (!defined NULL) */
/** \brief abstraction of an ISO-C:99 keyword for \p NULL */
#define TS_NULL NULL
#endif /* if (!defined NULL) */

#if (!defined SP_UINT8_C)
/** \brief Macro to define a constant of type uint8 */
#define SP_UINT8_C(x) ((uint8) x ## U)
#endif

#if (!defined SP_UINT16_C)
/** \brief Macro to define a constant of type uint16 */
#define SP_UINT16_C(x) ((uint16) x ## U)
#endif

#if (!defined SP_UINT32_C)
/** \brief Macro to define a constant of type uint32 */
#define SP_UINT32_C(x) ((uint32) x ## U)
#endif

#if (!defined SP_SINT8_C)
/** \brief Macro to define a constant of type sint8 */
/* MISRA-1 */ /* PRQA S 3453 1 */ /* macros used like functions. */
#define SP_SINT8_C(x) ((sint8) (x))
#endif

#if (!defined SP_SINT16_C)
/** \brief Macro to define a constant of type sint16 */
/* MISRA-1 */ /* PRQA S 3453 1 */ /* macros used like functions. */
#define SP_SINT16_C(x) ((sint16) (x))
#endif

#if (!defined SP_SINT32_C)
/** \brief Macro to define a constant of type sint32 */
/* MISRA-1 */ /* PRQA S 3453 1 */ /* macros used like functions. */
#define SP_SINT32_C(x) ((sint32) (x))
#endif

/*==================[type definitions]=======================================*/

/* Pointer to register types */

/** \brief pointer to 8bit volatile memory */
typedef volatile uint8*         ts_uint8_vp;
/** \brief pointer to 16bit volatile memory */
typedef volatile uint16*        ts_uint16_vp;
/** \brief pointer to 32bit volatile memory */
typedef volatile uint32*        ts_uint32_vp;

/** \brief pointer to signed 8bit volatile memory */
typedef volatile sint8*         ts_sint8_vp;
/** \brief pointer to signed 16bit volatile memory */
typedef volatile sint16*        ts_sint16_vp;
/** \brief pointer to signed 32bit volatile memory */
typedef volatile sint32*        ts_sint32_vp;

